{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Fluconazole, a triazole antifungal, has absolute oral bioavailability over 90% in humans, demonstrating that azole antifungals can achieve high systemic exposure; although fluconazole is more polar and soluble than the query, this supports a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ziprasidone, a lipophilic, poorly soluble drug with a basic amine and aryl chlorides, has absolute oral bioavailability of approximately 60% when taken with food, showing that solubility-limited lipophilic drugs can still exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Halofantrine, a highly lipophilic, poorly soluble drug with basic nitrogen and multiple aromatic chlorines, has an average absolute oral bioavailability of approximately 30% in humans, directly supporting F >= 20% for a physicochemically similar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Mosliciguat, a complex lipophilic drug, has an absolute oral bioavailability of 23.1%, just above the 20% threshold, indicating that even low-to-moderate F values in this chemical space still meet the high label.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Indomethacin oral bioavailability in preterm infants was only 13%, but this reflects immature gastrointestinal absorption in neonates and is not transferable to an adult oral bioavailability context; it is the only sub-20% evidence and does not outweigh the adult high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic imidazole antifungal with low predicted solubility. Most high-transfer experimental evidence from azole antifungals and lipophilic basic drugs shows oral bioavailability values above the 20% threshold (fluconazole >90%, ziprasidone ~60% fed, halofantrine ~30%, mosliciguat 23%). The only sub-20% evidence is indomethacin in preterm infants, a special population with immature absorption, and is not transferable to the adult query. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Food effects and solubility-limited absorption for the query are not directly quantified.",
    "Extrapolation from analogues with different physicochemical properties introduces uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

